import {dayKey,parseDay,moveDay,dayDiff,esc,money,dateLabel,avg,metrics,validateCheck} from './core.mjs';
import {PROGRAM} from './program.mjs';
import {gamesView,initGames} from './games.mjs';
import {createProgress} from './progress.mjs';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const S={user:null,demo:false,page:'home',profile:{},journey:{},settings:{},checks:[],journal:[],program:[],urges:[],reasons:[],posts:[],likes:new Set(),comments:{},feedPage:0,feedKind:'all',feedSearch:'',morePosts:false,month:dayKey().slice(0,7),authMode:'signin',authBusy:false,recovery:false,selectedStep:1,urge:null};
const TRIGGERS=['Stress','Solitude','Ennui','Fatigue','Habitude','Soirée','Émotion','Repas','Autre'];
let client=null,clientPromise=null,toastTimeout,installEvent=null,timerTick=null;
function notify(t){$('#notice').textContent=t;$('#notice').classList.add('on');clearTimeout(toastTimeout);toastTimeout=setTimeout(()=>$('#notice').classList.remove('on'),6500)}
function message(e){if(!navigator.onLine)return 'Hors connexion. Rien n’a été enregistré : réessaie avec Internet.';const t=String(e?.message||e||'Une erreur est survenue.');if(t.includes('Invalid login credentials'))return 'Adresse email ou mot de passe incorrect.';if(t.includes('Email not confirmed'))return 'Confirme ton email ou demande un nouveau lien.';if(t.includes('rate limit')||t.includes('security purposes'))return 'Trop de demandes rapprochées. Attends avant de réessayer.';if(t.includes('fetch')||t.includes('timeout')||t.includes('aborted'))return 'Connexion indisponible ou trop lente. Réessaie ; aucune sauvegarde n’est confirmée.';return t.slice(0,230)}
function checkResult(r){if(r.error)throw r.error;return r.data}
async function safeFetch(input,init={}){const controller=new AbortController();const abort=()=>controller.abort();if(init.signal?.aborted)abort();else init.signal?.addEventListener('abort',abort,{once:true});const t=setTimeout(abort,15000);try{return await fetch(input,{...init,signal:controller.signal,cache:'no-store'})}finally{clearTimeout(t);init.signal?.removeEventListener('abort',abort)}}
async function getClient(){if(client)return client;if(!clientPromise)clientPromise=(async()=>{const {createClient}=await import('https://esm.sh/@supabase/supabase-js@2.117.1');client=createClient('https://lnvtowdbbagwfbewnchz.supabase.co','sb_publishable_NejyPV0XbMiAW_yAmuIrhA_7_zDFYT7',{global:{fetch:safeFetch}});client.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'){S.recovery=true;setTimeout(passwordModal,0)}if(event==='SIGNED_OUT'&&!S.demo&&S.user)leave();if(event==='SIGNED_IN'&&session&&!S.authBusy&&!S.demo&&S.user?.id!==session.user.id)setTimeout(()=>enter(session.user).catch(e=>notify(message(e))),0)});return client})().catch(e=>{clientPromise=null;throw e});return Promise.race([clientPromise,new Promise((_,reject)=>setTimeout(()=>reject(Error('Chargement de la connexion trop lent. Réessaie.')),18000))])}
function field(name,label,value='',type='text',extra=''){return `<label>${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function area(name,label,value='',max=1000){return `<label>${label}<textarea name="${name}" maxlength="${max}" rows="4">${esc(value)}</textarea></label>`}
function closeModal(){$('#modal').close()}
function modal(title,body){$('#modalContent').innerHTML=`<div class="modal-top"><h2>${esc(title)}</h2><button type="button" class="close" data-action="close" aria-label="Fermer">×</button></div>${body}`;if(!$('#modal').open)$('#modal').showModal()}
function stat(label,value,detail=''){return `<div class="stat"><span>${label}</span><b>${value}</b><span>${detail}</span></div>`}
function select(name,label,options,value){return `<label>${label}<select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(value)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`}
function privateWrite(){if(!S.user)throw Error('Connecte-toi pour enregistrer ton suivi.');if(!S.demo&&!navigator.onLine)throw Error('Hors connexion.');if(!S.demo&&!S.settings.privacy_ack_at)throw Error('Ouvre Moi et valide les informations sur le stockage avant d’enregistrer.');}
async function ownRows(table,order='id',column='user_id',selectColumns='*'){const db=await getClient();const result=[];for(let offset=0;;offset+=500){const rows=checkResult(await db.from(table).select(selectColumns).eq(column,S.user.id).order(order,{ascending:true}).range(offset,offset+499));result.push(...rows);if(rows.length<500)return result}}
async function loadPrivate(){const db=await getClient(),uid=S.user.id;const values=await Promise.all([db.from('profiles').select('*').eq('id',uid).single(),db.from('sobriety_journeys').select('*').eq('user_id',uid).single(),db.from('user_settings').select('*').eq('user_id',uid).maybeSingle(),ownRows('daily_checkins','checkin_date'),db.from('journal_entries').select('*').eq('user_id',uid).order('entry_date',{ascending:false}).order('created_at',{ascending:false}).limit(50),db.from('program_progress').select('*').eq('user_id',uid).order('step'),db.from('urge_events').select('*').eq('user_id',uid).order('created_at',{ascending:false}).limit(50),db.from('reasons').select('*').eq('user_id',uid).order('position').limit(50)]);const [p,j,s,checks,notes,program,urges,reasons]=values;for(const r of [p,j,s,notes,program,urges,reasons])checkResult(r);if(S.demo||S.user?.id!==uid)return;Object.assign(S,{profile:p.data,journey:j.data,settings:s.data||{},checks,journal:notes.data,program:program.data,urges:urges.data,reasons:reasons.data});await progression.load();$('#loadError').hidden=true}
async function enter(user){progression.reset();Object.assign(S,{profile:{},journey:{},settings:{},checks:[],journal:[],program:[],urges:[],reasons:[],posts:[],likes:new Set(),comments:{}});S.user=user;S.demo=false;$('#welcome').hidden=true;$('#workspace').hidden=false;$('#demoBanner').hidden=true;$('#content').innerHTML='<div class="empty">Chargement de ton espace…</div>';try{await loadPrivate();S.selectedStep=PROGRAM.find(p=>!S.program.some(x=>x.step===p.step))?.step||30;render();if(S.recovery)passwordModal();else if(!S.settings.privacy_ack_at)privacyModal(true)}catch(e){$('#loadError').hidden=false;$('#loadError').textContent='Ton espace n’a pas pu être chargé. '+message(e);render();}}
function leave(){progression.reset();clearInterval(timerTick);Object.assign(S,{user:null,demo:false,profile:{},journey:{},settings:{},checks:[],journal:[],program:[],urges:[],reasons:[],posts:[],likes:new Set(),comments:{},urge:null,page:'home',recovery:false});closeModal();$('#welcome').hidden=false;$('#workspace').hidden=true;$('#authForm').reset();$('#authInfo').textContent='';}
function demo(){const today=dayKey();Object.assign(S,{demo:true,user:{id:'demo'},profile:{display_name:'Alex',username:'alex_demo',bio:'Un jour à la fois.'},journey:{started_at:parseDay(moveDay(today,-31)).toISOString(),weekly_spend_estimate:70,why_text:'Retrouver de la place pour les choses qui comptent.',goal_note:'Avancer à mon rythme.'},settings:{privacy_ack_at:new Date().toISOString(),risky_situation:'La fin de journée après le travail.',response_plan:'Prendre l’air quelques minutes et contacter une personne de confiance.',reminder_time:'20:00',hidden_authors:[]},checks:Array.from({length:22},(_,i)=>({id:'demo-check-'+i,checkin_date:moveDay(today,-i-1),sober_today:i!==5,mood:3+i%3,craving:i%6,note:'Exemple fictif de bilan.',sleep_hours:7+(i%2)/2,energy:3+i%2,trigger_tags:i%3===0?['Stress']:[]})),journal:[{id:'demo-note',entry_date:moveDay(today,-1),title:'Un petit pas',body:'Donnée fictive : j’ai pris le temps de préparer ma soirée.',kind:'victory',created_at:new Date().toISOString()}],program:[1,2,3].map(step=>({step,reflection:'Réflexion de démonstration.',completed_at:new Date().toISOString()})),urges:[],reasons:[],posts:[],likes:new Set(),comments:{},selectedStep:4,page:'home'});$('#welcome').hidden=true;$('#workspace').hidden=false;$('#demoBanner').hidden=false;$('#loadError').hidden=true;progression.seedDemo();render()}
function nextStep(){return PROGRAM.find(p=>!S.program.some(x=>x.step===p.step))||PROGRAM[29]}
function render(){if(!S.user)return;$('#headerDate').textContent=new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'});$('#avatar').textContent=(S.profile.display_name||'S').slice(0,1).toUpperCase();$$('[data-page]').forEach(b=>{b.classList.toggle('selected',b.dataset.page===S.page);if(b.closest('nav'))b.setAttribute('aria-current',b.dataset.page===S.page?'page':'false')});const f={home:homeView,journey:journeyView,journal:journalView,games:gamesView,community:communityView,profile:profileView,progress:()=>progression.view()}[S.page]||homeView;$('#content').innerHTML=f();}
function greeting(title,sub){return `<div class="greeting"><span class="eyebrow">TON ESPACE SOBRIZEN</span><h1>${title}</h1><p class="muted">${sub}</p></div>`}
function homeView(){return progression.home()}
function weekView(m){const craving=avg(m.week,'craving'),old=avg(m.previous,'craving'),delta=craving!==null&&old!==null?craving-old:null;return `<div class="row between"><div><span class="eyebrow">LES 7 DERNIERS JOURS</span><h2>Ton bilan, sans jugement.</h2></div><span class="tag">${m.week.length}/7 jours renseignés</span></div><p>${m.week.filter(x=>x.sober_today).length} jours sans alcool déclarés · humeur moyenne ${avg(m.week,'mood')?.toFixed(1)||'—'}/5 · sommeil ${avg(m.week,'sleep_hours')?.toFixed(1)||'—'} h.</p><p class="small">Envie moyenne : ${craving?.toFixed(1)||'—'}/10.${delta===null?' Comparaison disponible après avoir renseigné deux semaines.':` Écart avec les 7 jours précédents : ${delta>0?'+':''}${delta.toFixed(1)} point(s), sur les jours renseignés.`} Ces observations ne sont pas une évaluation médicale.</p>${cravingChart()}<div class="row"><button class="text" data-page="journey">Voir mon calendrier →</button><button class="text" data-action="journal-new">Écrire ma réflexion →</button></div>`}
function cravingChart(){const days=Array.from({length:14},(_,i)=>moveDay(dayKey(),i-13));return `<div class="chart" role="img" aria-label="Intensité des envies renseignées sur les 14 derniers jours">${days.map(d=>{const c=S.checks.find(x=>x.checkin_date===d),v=c?.craving;return `<div class="bar-col" title="${dateLabel(d)} : ${v??'non renseigné'}"><small>${v??'—'}</small><div class="bar" style="height:${v===undefined||v===null?2:Math.max(3,v*6)}px;opacity:${(v===undefined||v===null)?0.12:0.7}"></div><span class="bar-label">${d.slice(8)}</span></div>`}).join('')}</div><p class="small">Envie / 10 · Tiret = jour non renseigné.</p>`}
function journeyView(){const p=PROGRAM[S.selectedStep-1]||nextStep(),done=S.program.find(x=>x.step===p.step);return progression.journey()+`<section class="card" style="margin-top:18px"><div class="row between"><div><span class="eyebrow">30 ÉTAPES À TON RYTHME</span><h2>Un espace pour réfléchir et agir.</h2></div><span class="badge">${S.program.length}/30 terminées</span></div><div class="progress-track"><div style="width:${S.program.length/30*100}%"></div></div><div class="step-grid">${PROGRAM.map(x=>`<button class="${S.program.some(y=>y.step===x.step)?'done':''} ${x.step===p.step?'current':''}" data-action="step" data-step="${x.step}" aria-label="Étape ${x.step} : ${esc(x.title)}">${S.program.some(y=>y.step===x.step)?'✓ ':''}${x.step}</button>`).join('')}</div><span class="eyebrow">${esc(p.phase)} · Étape ${p.step}</span><h2>${esc(p.title)}</h2><p>${esc(p.lesson)}</p><div class="card peach"><h3>Ta petite action</h3><p>${esc(p.action)}</p></div><form id="programForm"><input type="hidden" name="step" value="${p.step}">${area('reflection',esc(p.prompt),done?.reflection||'',2000)}<button class="primary">${done?'Mettre à jour ma réflexion':'Marquer cette étape comme terminée'}</button></form><p class="small" style="margin-top:14px">Contenus de soutien non validés comme traitement. Aucun résultat ni délai d’arrêt n’est garanti.</p></section>`}
function journalView(){return greeting('Ton journal. Rien à prouver.','Un espace privé pour tes idées, tes victoires et les moments plus difficiles.')+`<div class="row between"><button class="primary" data-action="journal-new">+ Écrire une note</button><label class="search">Rechercher dans les 50 dernières notes<input id="journalSearch" type="search" placeholder="Un mot, un souvenir…"></label></div><div id="journalList" class="posts" style="margin-top:20px">${journalList('')}</div>`}
function journalList(search){const notes=S.journal.filter(n=>(n.title+' '+n.body).toLocaleLowerCase().includes(search.toLocaleLowerCase()));return notes.length?notes.map(n=>`<article class="card"><div class="row between"><span class="tag">${({reflection:'Réflexion',victory:'Victoire',difficult:'Moment difficile',plan:'Plan personnel'})[n.kind]}</span><small>${dateLabel(n.entry_date)}</small></div><h3 style="margin-top:14px">${esc(n.title)}</h3><p class="entry-body">${esc(n.body)}</p><div class="row"><button class="text" data-action="journal-edit" data-id="${esc(n.id)}">Modifier</button><button class="text" data-action="journal-delete" data-id="${esc(n.id)}">Supprimer</button></div></article>`).join(''):'<div class="card empty">Aucune note à afficher. Une phrase peut suffire pour commencer.</div>'}
function journalModal(id){const n=S.journal.find(x=>x.id===id)||{};modal(id?'Modifier ma note':'Écrire pour moi',`<p class="small">Privé vis-à-vis des autres membres. Jamais publié dans la communauté.</p><form id="journalForm"><input type="hidden" name="id" value="${esc(n.id||'')}"><div class="two-fields">${field('entry_date','Date',n.entry_date||dayKey(),'date',`required max="${dayKey()}"`)}${select('kind','Type',[['reflection','Réflexion'],['victory','Victoire'],['difficult','Moment difficile'],['plan','Plan personnel']],n.kind||'reflection')}</div>${field('title','Titre',n.title||'','text','required maxlength="120"')}${area('body','Ta note',n.body||'',5000)}<button class="primary full">Enregistrer ma note</button></form>`)}
async function loadFeed(append=false){if(S.demo){S.posts=[{id:'demo-post',author_id:'demo-other',body:'Exemple fictif : aujourd’hui j’ai préparé ma soirée différemment.',kind:'victory',created_at:new Date().toISOString(),profiles:{display_name:'Camille · Démo',username:'camille_demo'},post_likes:[{count:2}],comments:[{count:0}]}];S.morePosts=false;return}const db=await getClient();let q=db.from('posts').select('id,author_id,kind,body,created_at,profiles!posts_author_id_fkey(display_name,username),post_likes(count),comments(count)').order('created_at',{ascending:false}).order('id',{ascending:false});if(S.feedKind!=='all')q=q.eq('kind',S.feedKind);if(S.feedSearch)q=q.ilike('body','%'+S.feedSearch.replace(/[%_]/g,'')+'%');const rows=checkResult(await q.range(S.feedPage*20,S.feedPage*20+19));const liked=rows.length?checkResult(await db.from('post_likes').select('post_id').eq('user_id',S.user.id).in('post_id',rows.map(x=>x.id))):[];if(!append)S.likes=new Set();liked.forEach(x=>S.likes.add(x.post_id));S.posts=append?[...S.posts,...rows]:rows;S.morePosts=rows.length===20;}
function communityView(){return greeting('Une communauté, pas une comparaison.','Les publications sont visibles par les membres connectés. Ne partage pas d’informations que tu souhaites garder privées.')+`<div class="row between"><button class="primary" data-action="post-new">+ Partager</button><button class="text" data-action="feed-refresh">Actualiser</button></div><div class="filters">${[['all','Tout'],['victory','Victoires'],['struggle','Moments difficiles'],['question','Questions'],['share','Partages']].map(([v,t])=>`<button class="${S.feedKind===v?'selected':''}" data-action="feed-kind" data-kind="${v}">${t}</button>`).join('')}</div><form id="feedSearchForm" class="row"><label class="search" style="flex:1">Rechercher<input name="search" value="${esc(S.feedSearch)}" maxlength="80" type="search"></label><button class="secondary">Chercher</button></form><p class="small">Échanges entre membres, sans suivi médical ni surveillance d’urgence. Les signalements demandent un examen manuel.</p><div class="posts">${postList()}</div>${S.morePosts?'<button class="secondary full" style="margin-top:15px" data-action="feed-more">Afficher la suite</button>':''}`}
function postList(){const rows=S.posts.filter(p=>!(S.settings.hidden_authors||[]).includes(p.author_id));return rows.length?rows.map(p=>`<article class="card"><div class="post-top"><div class="row"><span class="avatar">${esc((p.profiles?.display_name||'M').slice(0,1))}</span><div><b>${esc(p.profiles?.display_name||'Membre')}</b><div class="small">@${esc(p.profiles?.username||'membre')} · ${dateLabel(dayKey(new Date(p.created_at)))}</div></div></div><span class="tag">${({victory:'Victoire',struggle:'Difficulté',share:'Partage',question:'Question'})[p.kind]}</span></div><p class="entry-body">${esc(p.body)}</p><div class="post-actions"><button class="secondary" data-action="like" data-id="${esc(p.id)}" aria-pressed="${S.likes.has(p.id)}">${S.likes.has(p.id)?'♥':'♡'} ${p.post_likes?.[0]?.count||0}</button><button class="secondary" data-action="comments" data-id="${esc(p.id)}">Commentaires (${p.comments?.[0]?.count||0})</button>${p.author_id===S.user.id?`<button class="text" data-action="post-edit" data-id="${esc(p.id)}">Modifier</button><button class="text" data-action="post-delete" data-id="${esc(p.id)}">Supprimer</button>`:`<button class="text" data-action="report" data-id="${esc(p.id)}">Signaler</button><button class="text" data-action="hide-author" data-id="${esc(p.author_id)}">Masquer pour moi</button>`}</div></article>`).join(''):'<article class="card empty">Aucune publication à afficher. Partage seulement ce que tu souhaites.</article>'}
function postModal(id){const p=S.posts.find(x=>x.id===id)||{};modal(id?'Modifier ma publication':'Partager avec les membres',`<p class="small">Visible par les membres, avec ton nom affiché et ton pseudo. Pour une note privée, utilise le Journal.</p><form id="postForm"><input type="hidden" name="id" value="${esc(id||'')}">${select('kind','Type',[['share','Partage'],['victory','Victoire'],['struggle','Moment difficile'],['question','Question']],p.kind||'share')}${area('body','Message',p.body||'',2000)}<label class="checklabel"><input type="checkbox" required> Je souhaite partager ce message dans la communauté.</label><button class="primary full">${id?'Enregistrer les modifications':'Publier'}</button></form>`)}
async function commentsModal(id,more=false){const db=S.demo?null:await getClient();const old=more?(S.comments[id]||[]):[];const rows=S.demo?(S.comments[id]||[]):checkResult(await db.from('comments').select('id,author_id,body,created_at,profiles!comments_author_id_fkey(display_name)').eq('post_id',id).order('created_at').order('id').range(old.length,old.length+19));S.comments[id]=more?[...old,...rows]:rows;modal('Commentaires',`<div>${S.comments[id].map(c=>`<div class="comment"><b>${esc(c.profiles?.display_name||'Membre')}</b><p class="entry-body">${esc(c.body)}</p>${c.author_id===S.user.id?`<button class="text" data-action="comment-delete" data-id="${esc(c.id)}" data-post="${esc(id)}">Supprimer mon commentaire</button>`:`<button class="text" data-action="report-comment" data-id="${esc(c.id)}">Signaler</button>`}</div>`).join('')||'<p class="small">Aucun commentaire pour le moment.</p>'}</div>${rows.length===20?`<button class="text" data-action="comments-more" data-id="${esc(id)}">Voir la suite</button>`:''}<form id="commentForm"><input type="hidden" name="post_id" value="${esc(id)}">${area('body','Répondre avec bienveillance','',1000)}<button class="primary full">Publier le commentaire</button></form>`)}
function profileView(){return greeting('Ton espace, tes choix.','Ton profil communautaire et ton suivi personnel sont séparés.')+`<div class="grid equal"><section class="card"><span class="eyebrow">VISIBLE PAR LES MEMBRES</span><h2>Mon profil</h2><form id="profileForm">${field('display_name','Nom affiché',S.profile.display_name||'','text','required maxlength="40"')}${field('username','Pseudo',S.profile.username||'','text','required minlength="3" maxlength="30" pattern="[a-z0-9_.]{3,30}"')}${area('bio','Bio publique',S.profile.bio||'',300)}<button class="primary">Enregistrer le profil</button></form></section><section class="card peach"><span class="eyebrow">PRIVÉ</span><h2>Mon cap</h2><p class="entry-body">${esc(S.journey.why_text||'Ajoute ta raison personnelle.')}</p><p>${esc(S.journey.goal_note||'')}</p><button class="secondary" data-page="progress">Mon cap et mes courbes →</button><button class="text" data-action="journey-settings">Mes paramètres de suivi</button>${journeyDateSummary()}<div class="list-item"><h3>Mes raisons personnelles</h3>${S.reasons.map(r=>`<p><b>${esc(r.title)}</b><br>${esc(r.detail||'')}</p>`).join('')||'<p class="small">Ajoute une raison qui te donne envie d’avancer.</p>'}<button class="text" data-action="reason-new">+ Ajouter une raison</button></div></section></div><section class="card" style="margin-top:18px"><span class="eyebrow">MON PLAN PERSONNEL · PRIVÉ</span><h2>Préparer les moments difficiles.</h2><form id="settingsForm"><div class="two-fields">${field('support_name','Personne de confiance (facultatif)',S.settings.support_name||'','text','maxlength="80"')}${field('support_phone','Téléphone (facultatif)',S.settings.support_phone||'','tel','maxlength="30"')}</div>${area('risky_situation','Si cette situation arrive…',S.settings.risky_situation||'',1000)}${area('response_plan','Alors, mon premier pas sera…',S.settings.response_plan||'',1500)}${field('reminder_time','Heure souhaitée de mon rappel calendrier',String(S.settings.reminder_time||'20:00').slice(0,5),'time','required')}<label class="checklabel"><input type="checkbox" name="privacy" required ${S.settings.privacy_ack_at?'checked':''}> J’accepte d’enregistrer volontairement ce suivi personnel dans Supabase après lecture des informations. <button class="text" type="button" data-action="privacy">Données & limites</button></label><button class="primary">Enregistrer mon plan</button></form><p class="small" style="margin-top:15px">Le téléphone reste privé. Aucun appel, SMS ni notification n’est envoyé automatiquement.</p><button class="secondary" data-action="calendar-reminder">Créer mon rappel calendrier</button><p class="small">Télécharge un rendez-vous récurrent à importer dans ton calendrier. Ce n’est pas une notification push de Sobrizen.</p></section><section class="card" style="margin-top:18px"><span class="eyebrow">MES DONNÉES & MON APP</span><div class="row"><button class="secondary" data-action="export">Exporter mon suivi</button><button class="secondary" data-action="install">Installer l’application</button><button class="secondary" data-action="theme">Changer le thème</button><button class="text" data-action="unhide">Réafficher les membres masqués</button><button class="text" data-action="logout">Se déconnecter</button></div><p class="small" style="margin-top:12px">L’export est un fichier non chiffré à conserver en lieu sûr. Il n’est pas une sauvegarde automatique ni une suppression de compte.</p></section>`}
function journeyDateSummary(){return progression.dateSummary()}
function journeyDateModal(){progression.openDate()}
async function updateJourney(changes){privateWrite();const user=S.user,uid=user.id,demo=S.demo;let saved;if(demo){saved={...S.journey,...changes}}else{const db=await getClient();if(S.user!==user||S.demo!==demo)return false;privateWrite();saved=checkResult(await db.from('sobriety_journeys').update(changes).eq('user_id',uid).select().single());}if(S.user!==user||S.demo!==demo)return false;S.journey={...S.journey,...saved};return true}
function journeySettings(){modal('Mes raisons d’avancer',`<form id="journeyForm">${area('why','Mon pourquoi',S.journey.why_text||'',1000)}${area('goal','Mon objectif personnel',S.journey.goal_note||'',500)}<button class="primary full">Enregistrer mes raisons</button></form>`)}
function checkModal(date=dayKey(),lapse=false){
 const c=S.checks.find(x=>x.checkin_date===date)||{};
 const sober=lapse?'false':c.sober_today===undefined?'':String(c.sober_today);
 modal('Mon bilan · '+dateLabel(date),`<form id="checkForm"><input type="hidden" name="checkin_date" value="${date}">
 ${select('sober_today','Alcool',[['','Choisir'],['true','Sans alcool'],['false','Avec consommation']],sober).replace('<select ','<select required ')}
 <div class="two-fields tr-feeling-quick">${select('mood','Humeur',[['','Choisir'],[1,'1 · Très difficile'],[2,'2 · Difficile'],[3,'3 · Moyenne'],[4,'4 · Bonne'],[5,'5 · Très bonne']],c.mood??'').replace('<select ','<select required ')}${select('craving','Envie d’alcool',[['','Choisir'],...Array.from({length:11},(_,i)=>[i,i===0?'0 · Aucune':i===10?'10 · Très forte':i+' / 10'])],c.craving??'').replace('<select ','<select required ')}</div>
 <details class="check-feelings"><summary>Ajouter des détails <span class="small">(facultatif)</span></summary>
 ${select('energy','Énergie',[['','Non renseignée'],[1,'1 · Très basse'],[2,'2 · Basse'],[3,'3 · Moyenne'],[4,'4 · Bonne'],[5,'5 · Très bonne']],c.energy||'')}
 ${field('sleep_hours','Sommeil (heures)',c.sleep_hours??'','number','min="0" max="24" step="0.5"')}
 <fieldset style="border:1px solid var(--line);border-radius:12px"><legend>Situations du jour</legend>${TRIGGERS.map(t=>`<label class="checklabel"><input type="checkbox" name="trigger_tags" value="${t}" ${(c.trigger_tags||[]).includes(t)?'checked':''}>${t}</label>`).join('')}</fieldset>
 ${area('note',lapse?'Mon prochain pas':'Ma note',c.note||'',1000)}
 </details>
 <p class="small">En cas de symptômes de manque, demande une aide médicale. Si tu as bu, ne conduis pas.</p>
 <button class="primary full">Enregistrer</button></form>`);
 progression.enhanceCheck();
}
function privacyModal(consent=false){modal('Données & limites',`<p>Sobrizen est une bêta de suivi personnel, pas un dispositif de diagnostic, un service d’urgence ou une garantie d’arrêt.</p><p>Avec un compte, tes bilans, quantités d’alcool, dépenses, objectifs successifs, notes, envies et réflexions sont envoyés à Supabase et associés à ton identifiant. Les règles d’accès les séparent des autres membres ; l’administrateur du projet conserve un accès technique. Ce n’est pas un chiffrement de bout en bout.</p><p>Ton nom affiché, ton pseudo, ta bio et tes publications sont visibles par les membres. Évite les informations identifiantes ou très sensibles dans la communauté. La démo ne sauvegarde pas ses données.</p><p>Tu peux exporter ton suivi et supprimer tes notes ou publications depuis leur écran. La suppression complète d’un compte n’est pas encore disponible dans cette version.</p><p>Les exercices et le programme peuvent être consultés hors ligne après chargement. Le suivi et la connexion nécessitent Internet. Aucun service payant, chatbot IA, publicité ni traqueur analytique n’est ajouté par cette évolution.</p><p class="small">Les mentions légales, la politique de confidentialité complète et les procédures de modération restent à finaliser avant une ouverture publique commerciale.</p>${consent?'<form id="consentForm"><label class="checklabel"><input type="checkbox" required> J’accepte de sauvegarder volontairement mon suivi dans les conditions décrites.</label><button class="primary full">Continuer avec le suivi</button></form>':''}`)}
function helpModal(){const phone=String(S.settings.support_phone||'').replace(/[^+\d]/g,'');modal('Un peu de soutien, maintenant.',`<div class="error-box"><b>La sécurité d’abord.</b> Après une réduction ou un arrêt : tremblements importants, confusion, hallucinations, convulsions ou malaise sévère nécessitent une aide médicale urgente. En France, appelle le 15 ou le 112. N’attends pas la fin du minuteur.</div><p>Les outils ci-dessous proposent une pause. Ils ne traitent pas un sevrage et ne garantissent pas la disparition d’une envie.</p><div class="row"><button class="primary" data-action="urge">Pause de 10 minutes</button><button class="secondary" data-action="breath">Respiration douce</button><button class="secondary" data-action="ground">Revenir au présent</button></div>${S.journey.why_text?`<div class="card peach" style="margin-top:16px"><span class="eyebrow">MON POURQUOI</span><p class="entry-body">${esc(S.journey.why_text)}</p></div>`:''}${S.settings.response_plan?`<p class="entry-body" style="margin-top:16px"><b>Mon plan :</b> ${esc(S.settings.response_plan)}</p>`:''}<div class="row" style="margin-top:18px">${phone?`<a class="secondary" style="padding:12px;border-radius:12px" href="tel:${phone}">Appeler ${esc(S.settings.support_name||'mon contact')}</a>`:''}<a href="tel:0980980930">Alcool Info Service : 0 980 980 930</a><a href="tel:15">15 · Urgence France</a><a href="tel:112">112 · Urgence UE</a></div><p class="small" style="margin-top:15px">Alcool Info Service : 8 h à 2 h, 7 j/7, appel non surtaxé. Hors de France, utilise une ressource locale adaptée.</p><p class="small">Informations : <a href="https://www.ameli.fr/assure/sante/themes/alcool-sante/arreter-consommation-cas-dependance" target="_blank" rel="noopener noreferrer">Assurance Maladie</a> · <a href="https://www.alcool-info-service.fr/" target="_blank" rel="noopener noreferrer">Alcool Info Service</a>.</p>`)}
function urgeModal(){const active=S.urge?.deadline;modal('Les prochaines minutes, seulement.',`<p>Choisis un endroit sûr. Un verre d’eau, une activité calme ou un appel peuvent faire partie de ta pause.</p><div id="timer" class="timer">10:00</div><p id="timerNote" class="small" style="text-align:center">Le minuteur ne prédit pas la durée de ton envie.</p><form id="urgeStartForm"><label>Intensité avant : <output id="beforeValue">${S.urge?.before||5}</output>/10<input name="before" type="range" min="1" max="10" value="${S.urge?.before||5}" data-output="beforeValue" ${active?'disabled':''}></label>${select('strategy','Mon outil',[['pause','Pause dans un lieu sûr'],['appel','Contacter quelqu’un'],['ancrage','Ancrage dans le présent'],['respiration','Respiration confortable']],S.urge?.strategy||'pause')}<button class="primary full">${active?'Recommencer 10 minutes':'Démarrer ma pause'}</button></form><form id="urgeEndForm" ${active?'':'hidden'}><label>Intensité maintenant : <output id="afterValue">5</output>/10<input name="after" type="range" min="0" max="10" value="5" data-output="afterValue"></label><button class="secondary full">Enregistrer mon ressenti</button></form><button class="text" data-action="help">Revenir à l’aide et aux contacts</button><p class="safety">Symptômes de manque ou malaise : demande une aide médicale, sans attendre le minuteur.</p>`);tickTimer()}
function tickTimer(){if(!$('#timer')||!S.urge?.deadline)return;const seconds=Math.max(0,Math.ceil((S.urge.deadline-Date.now())/1000));$('#timer').textContent=`${String(Math.floor(seconds/60)).padStart(2,'0')}:${String(seconds%60).padStart(2,'0')}`;if(!seconds)$('#timerNote').textContent='10 minutes écoulées. Comment est ton envie maintenant ? Elle peut être encore présente.'}
function passwordModal(){modal('Choisir un nouveau mot de passe',`<form id="passwordForm">${field('password','Nouveau mot de passe','','password','required minlength="10" autocomplete="new-password"')}${field('confirm','Confirmer le mot de passe','','password','required minlength="10" autocomplete="new-password"')}<button class="primary full">Enregistrer le mot de passe</button></form>`)}
function download(filename,text,type){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
async function exportData(){privateWrite();const all=S.demo?{checks:S.checks,journal:S.journal,urges:S.urges,reasons:S.reasons,program:S.program}:Object.fromEntries(await Promise.all([['checks','daily_checkins','checkin_date'],['journal','journal_entries','id'],['urges','urge_events','id'],['reasons','reasons','id'],['program','program_progress','step']].map(async([key,t,order])=>[key,await ownRows(t,order)])));download('sobrizen-mon-suivi-'+dayKey()+'.json',JSON.stringify({version:4,...await progression.extraExport(),exported_at:new Date().toISOString(),demo:S.demo,profile:S.profile,journey:S.journey,settings:S.settings,...all},null,2),'application/json');notify('Export téléchargé. Conserve ce fichier personnel en lieu sûr.')}
function reminder(){const time=String(S.settings.reminder_time||'20:00').slice(0,5);const date=moveDay(dayKey(),1).replaceAll('-','');const stamp=new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,'');download('mon-rendez-vous.ics',['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Sobrizen//Rappel personnel//FR','BEGIN:VEVENT','UID:'+crypto.randomUUID()+'@sobrizen.com','DTSTAMP:'+stamp,'DTSTART:'+date+'T'+time.replace(':','')+'00','DURATION:PT5M','RRULE:FREQ=DAILY','SUMMARY:Mon rendez-vous personnel','DESCRIPTION:Prendre quelques minutes pour mon bilan.','BEGIN:VALARM','TRIGGER:-PT5M','ACTION:DISPLAY','DESCRIPTION:Mon rendez-vous personnel','END:VALARM','END:VEVENT','END:VCALENDAR',''].join('\r\n'),'text/calendar');notify('Importe le fichier dans ton calendrier. Vérifie l’heure et les rappels après import.')}
async function saveRow(table,row,conflict){privateWrite();const db=await getClient();return checkResult(await db.from(table).upsert({...row,user_id:S.user.id},{onConflict:conflict}).select().single())}
async function refresh(){if(!S.demo)await loadPrivate();render()}
const actionHandlers={
 close:()=>closeModal(),signin:()=>setAuthMode('signin'),signup:()=>setAuthMode('signup'),demo,privacy:()=>privacyModal(),help:helpModal,urge:urgeModal,
 breath:()=>modal('Respirer sans forcer',`<div class="breath" aria-hidden="true">◌</div><p>Installe-toi confortablement. Inspire doucement, puis expire un peu plus lentement, sans retenir ton souffle. Garde un rythme confortable plutôt que de suivre l’animation à tout prix.</p><p class="small">Arrête en cas de vertige ou d’inconfort. Cet exercice ne traite pas le sevrage.</p><button class="primary full" data-action="help">Revenir à mon espace d’aide</button>`),
 ground:()=>modal('Revenir à ce qui t’entoure',`<p>Dans un lieu sûr, prends ton temps pour remarquer :</p><ol class="tool-steps"><li>5 choses que tu vois.</li><li>4 choses que tu peux sentir au toucher.</li><li>3 sons autour de toi.</li><li>2 odeurs, ou simplement 2 sensations neutres.</li><li>1 chose dont tu as besoin maintenant.</li></ol><p class="small">Adapte l’exercice à tes capacités. Aucun besoin de réussir parfaitement.</p><button class="primary full" data-action="help">Revenir à l’aide</button>`),
 theme:()=>{document.body.classList.toggle('dark');try{localStorage.setItem('sobrizen-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}},
 logout:async()=>{if(S.user&&!S.demo){const db=await getClient();checkResult(await db.auth.signOut({scope:'local'}))}leave()},
 check:()=>progression.openOccasion(),
 'month-prev':()=>{const d=parseDay(S.month+'-01');d.setMonth(d.getMonth()-1);S.month=dayKey(d).slice(0,7);render()},
 'month-next':()=>{const d=parseDay(S.month+'-01');d.setMonth(d.getMonth()+1);S.month=dayKey(d).slice(0,7);render()},
 step:b=>{S.selectedStep=Math.min(30,Math.max(1,Number(b.dataset.step)||1));S.page='journey';render();},
 'journey-settings':()=>progression.openSettings(),'journey-date':journeyDateModal,'journal-new':()=>journalModal(),'journal-edit':b=>journalModal(b.dataset.id),
 'journal-delete':async b=>{if(!confirm('Supprimer définitivement cette note personnelle ?'))return;privateWrite();if(!S.demo)checkResult(await (await getClient()).from('journal_entries').delete().eq('id',b.dataset.id).eq('user_id',S.user.id));S.journal=S.journal.filter(x=>x.id!==b.dataset.id);render();notify('Note supprimée.')},
 'reason-new':()=>modal('Une raison qui compte',`<form id="reasonForm">${field('title','Ma raison','','text','required maxlength="120"')}${area('detail','Un peu plus de détail','',500)}<button class="primary full">Enregistrer cette raison</button></form>`),
 'post-new':()=>postModal(),'post-edit':b=>postModal(b.dataset.id),
 'post-delete':async b=>{if(!confirm('Supprimer ta publication et les commentaires associés ?'))return;if(!S.demo)checkResult(await (await getClient()).from('posts').delete().eq('id',b.dataset.id).eq('author_id',S.user.id));S.posts=S.posts.filter(p=>p.id!==b.dataset.id);render();notify('Publication supprimée.')},
 'feed-refresh':async()=>{S.feedPage=0;await loadFeed();render()},'feed-kind':async b=>{S.feedKind=b.dataset.kind;S.feedPage=0;await loadFeed();render()},'feed-more':async()=>{S.feedPage++;try{await loadFeed(true)}catch(e){S.feedPage--;throw e}render()},
 like:async b=>{const id=b.dataset.id,liked=S.likes.has(id),p=S.posts.find(x=>x.id===id);if(!S.demo){const db=await getClient();checkResult(await(liked?db.from('post_likes').delete().eq('post_id',id).eq('user_id',S.user.id):db.from('post_likes').insert({post_id:id,user_id:S.user.id})))}liked?S.likes.delete(id):S.likes.add(id);p.post_likes=[{count:Math.max(0,(p.post_likes?.[0]?.count||0)+(liked?-1:1))}];render()},
 comments:b=>commentsModal(b.dataset.id),'comments-more':b=>commentsModal(b.dataset.id,true),
 'comment-delete':async b=>{if(!confirm('Supprimer ton commentaire ?'))return;if(!S.demo)checkResult(await(await getClient()).from('comments').delete().eq('id',b.dataset.id).eq('author_id',S.user.id));await commentsModal(b.dataset.post)},
 report:b=>reportModal(b.dataset.id,false),'report-comment':b=>reportModal(b.dataset.id,true),
 'hide-author':async b=>{privateWrite();if(!confirm('Masquer les publications de ce membre pour ton compte ?'))return;const hidden=[...new Set([...(S.settings.hidden_authors||[]),b.dataset.id])];if(!S.demo)S.settings=await saveRow('user_settings',{...S.settings,hidden_authors:hidden},'user_id');else S.settings.hidden_authors=hidden;render()},
 unhide:async()=>{privateWrite();if(!S.demo)S.settings=await saveRow('user_settings',{...S.settings,hidden_authors:[]},'user_id');else S.settings.hidden_authors=[];notify('Les publications des membres ne sont plus masquées.')},
 export:exportData,'calendar-reminder':reminder,
 install:async()=>{if(installEvent){await installEvent.prompt();await installEvent.userChoice;installEvent=null}else modal('Installer Sobrizen',`<p><b>Sur iPhone / iPad :</b> ouvre Sobrizen dans Safari, puis Partager → Sur l’écran d’accueil. Active l’ouverture comme app web si cette option est proposée.</p><p><b>Sur Android :</b> dans Chrome, utilise le menu → Installer l’application ou Ajouter à l’écran d’accueil.</p><p class="small">Les libellés varient selon le navigateur. Le suivi nécessite Internet ; les exercices peuvent rester disponibles hors ligne après chargement.</p>`)},
 forgot:async()=>{const email=$('#authForm').elements.email.value.trim();if(!email)return notify('Renseigne ton adresse email dans le formulaire.');checkResult(await(await getClient()).auth.resetPasswordForEmail(email,{redirectTo:location.origin}));$('#authInfo').textContent='Si un compte correspond à cette adresse, un email de réinitialisation sera envoyé.'},
 resend:async()=>{const email=$('#authForm').elements.email.value.trim();if(!email)return notify('Renseigne ton adresse email dans le formulaire.');checkResult(await(await getClient()).auth.resend({type:'signup',email,options:{emailRedirectTo:location.origin}}));$('#authInfo').textContent='Si une confirmation est nécessaire, un nouveau lien sera envoyé. Utilise seulement le plus récent.'}
};
function reportModal(id,isComment){modal('Signaler un contenu',`<p class="small">Le signalement sera enregistré pour examen manuel par l’administrateur. Ce n’est pas un service d’urgence.</p><form id="reportForm"><input type="hidden" name="target" value="${isComment?'comment':'post'}"><input type="hidden" name="id" value="${esc(id)}">${area('reason','Pourquoi souhaites-tu le signaler ?','',500)}<button class="primary full">Envoyer le signalement</button></form>`)}
function setAuthMode(mode){S.authMode=mode;$('#nameLabel').hidden=mode!=='signup';$('#signupConsent').hidden=mode!=='signup';$('#authForm').elements.consent.required=mode==='signup';$('#authForm').elements.password.minLength=mode==='signup'?10:1;$('#authForm').elements.password.autocomplete=mode==='signup'?'new-password':'current-password';$('#signinTab').classList.toggle('selected',mode==='signin');$('#signupTab').classList.toggle('selected',mode==='signup');$('#authSubmit').textContent=mode==='signup'?'Créer mon compte':'Se connecter'}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.page){S.page=b.dataset.page;if(S.page==='community'){try{S.feedPage=0;await loadFeed()}catch(err){notify(message(err))}}render();window.scrollTo({top:0,behavior:'instant'});return}if(!b.dataset.action)return;e.preventDefault();const fn=actionHandlers[b.dataset.action];if(!fn)return;b.disabled=true;try{await fn(b)}catch(err){notify(message(err))}finally{b.disabled=false}});
document.addEventListener('input',e=>{if(e.target.dataset.output){const out=document.getElementById(e.target.dataset.output);if(out)out.textContent=e.target.value}if(e.target.id==='journalSearch')$('#journalList').innerHTML=journalList(e.target.value)});
document.addEventListener('submit',async e=>{e.preventDefault();const form=e.target,data=new FormData(form),v=n=>String(data.get(n)||'').trim(),button=e.submitter||form.querySelector('button[type=submit],button.primary');if(button?.disabled)return;if(button)button.disabled=true;try{switch(form.getAttribute('id')){
case 'authForm':{S.authBusy=true;const db=await getClient(),email=v('email'),password=String(data.get('password')||'');const result=S.authMode==='signup'?await db.auth.signUp({email,password,options:{emailRedirectTo:location.origin,data:{display_name:v('display_name')||'Nouveau membre'}}}):await db.auth.signInWithPassword({email,password});const d=checkResult(result);if(d.session){await enter(d.user)}else $('#authInfo').textContent='Consulte ton email pour confirmer ton inscription. Un lien déjà utilisé ou expiré peut nécessiter un nouvel envoi.';break;}
case 'consentForm':{const row={user_id:S.user.id,privacy_ack_at:new Date().toISOString()};S.settings=checkResult(await(await getClient()).from('user_settings').upsert(row,{onConflict:'user_id'}).select().single());closeModal();render();notify('Ton choix est enregistré.');break;}
case 'checkForm':{privateWrite();const rec=validateCheck({user_id:S.user.id,checkin_date:v('checkin_date'),sober_today:v('sober_today')==='true'?true:v('sober_today')==='false'?false:null,mood:Number(v('mood')),energy:v('energy')?Number(v('energy')):null,craving:Number(v('craving')),sleep_hours:v('sleep_hours')===''?null:Number(v('sleep_hours')),note:v('note')||null,trigger_tags:data.getAll('trigger_tags')});const saved=S.demo?{...rec,id:S.checks.find(x=>x.checkin_date===rec.checkin_date)?.id||crypto.randomUUID()}:await saveRow('daily_checkins',rec,'user_id,checkin_date');S.checks=[...S.checks.filter(x=>x.checkin_date!==rec.checkin_date),saved];closeModal();render();notify(S.demo?'Démo mise à jour, sans sauvegarde.':'Bilan enregistré. Ton historique est conservé.');break;}
case 'journeyForm':{if(!await updateJourney({why_text:v('why')||null,goal_note:v('goal')||null}))break;if(document.contains(form))closeModal();render();notify('Raisons enregistrées.');break;}
case 'programForm':{privateWrite();const step=Number(v('step'));if(!PROGRAM.some(p=>p.step===step))throw Error('Étape invalide.');const old=S.program.find(x=>x.step===step);const row={user_id:S.user.id,step,reflection:v('reflection')||null,completed_at:old?.completed_at||new Date().toISOString()};const saved=S.demo?row:await saveRow('program_progress',row,'user_id,step');S.program=[...S.program.filter(x=>x.step!==step),saved];render();notify('Étape enregistrée. Avance à ton rythme.');break;}
case 'journalForm':{privateWrite();const date=v('entry_date');parseDay(date);if(date>dayKey())throw Error('Choisis une date passée ou aujourd’hui.');if(!v('body'))throw Error('Écris au moins une phrase.');const row={id:v('id')||crypto.randomUUID(),user_id:S.user.id,entry_date:date,title:v('title'),body:v('body'),kind:v('kind')};const saved=S.demo?{...row,created_at:new Date().toISOString()}:await saveRow('journal_entries',row,'id');S.journal=[saved,...S.journal.filter(x=>x.id!==saved.id)].sort((a,b)=>b.entry_date.localeCompare(a.entry_date));closeModal();render();notify('Note enregistrée dans ton journal privé.');break;}
case 'settingsForm':{if(!S.user)throw Error('Connecte-toi.');if(!data.get('privacy'))throw Error('La validation du stockage est nécessaire.');const phone=v('support_phone');if(phone&&!/^\+?[0-9\s().-]{5,30}$/.test(phone))throw Error('Vérifie le numéro de téléphone.');const row={user_id:S.user.id,support_name:v('support_name')||null,support_phone:phone||null,risky_situation:v('risky_situation')||null,response_plan:v('response_plan')||null,reminder_time:v('reminder_time'),privacy_ack_at:S.settings.privacy_ack_at||new Date().toISOString(),hidden_authors:S.settings.hidden_authors||[]};S.settings=S.demo?row:checkResult(await(await getClient()).from('user_settings').upsert(row,{onConflict:'user_id'}).select().single());render();notify('Plan personnel enregistré. Aucun message n’a été envoyé.');break;}
case 'profileForm':{const row={display_name:v('display_name'),username:v('username').toLowerCase(),bio:v('bio')||null};if(!/^[a-z0-9_.]{3,30}$/.test(row.username))throw Error('Pseudo : 3 à 30 lettres minuscules, chiffres, points ou tirets bas.');S.profile=S.demo?{...S.profile,...row}:checkResult(await(await getClient()).from('profiles').update(row).eq('id',S.user.id).select().single());render();notify('Profil enregistré.');break;}
case 'reasonForm':{privateWrite();const row={user_id:S.user.id,title:v('title'),detail:v('detail')||null,position:S.reasons.length};const saved=S.demo?{...row,id:crypto.randomUUID()}:checkResult(await(await getClient()).from('reasons').insert(row).select().single());S.reasons.push(saved);closeModal();render();notify('Raison personnelle enregistrée.');break;}
case 'urgeStartForm':{if(S.urge?.deadline&&!confirm('Recommencer le minuteur sans enregistrer cette pause ?'))break;const before=Number(data.get('before')||S.urge?.before||5);S.urge={id:crypto.randomUUID(),before,strategy:v('strategy'),deadline:Date.now()+600000};clearInterval(timerTick);timerTick=setInterval(tickTimer,500);urgeModal();break;}
case 'urgeEndForm':{privateWrite();if(!S.urge)throw Error('Démarre une pause avant de noter son résultat.');const row={id:S.urge.id,user_id:S.user.id,intensity:S.urge.before,strategy:S.urge.strategy,outcome:'Intensité après la pause : '+v('after')+'/10'};if(!S.demo)checkResult(await(await getClient()).from('urge_events').upsert(row,{onConflict:'id'}).select().single());clearInterval(timerTick);S.urge=null;closeModal();notify('Ressenti enregistré. Une envie encore présente n’est pas un échec.');break;}
case 'postForm':{if(!v('body'))throw Error('Écris ton message avant de publier.');const id=v('id'),row={author_id:S.user.id,kind:v('kind'),body:v('body')};if(S.demo){if(id){Object.assign(S.posts.find(p=>p.id===id),row)}else S.posts.unshift({...row,id:crypto.randomUUID(),created_at:new Date().toISOString(),profiles:S.profile,post_likes:[{count:0}],comments:[{count:0}]})}else{const db=await getClient();checkResult(await(id?db.from('posts').update(row).eq('id',id).eq('author_id',S.user.id):db.from('posts').insert(row)));S.feedPage=0;await loadFeed()}closeModal();S.page='community';render();notify(S.demo?'Publication fictive ajoutée.':'Publication enregistrée.');break;}
case 'commentForm':{if(!v('body'))throw Error('Écris une réponse.');const id=v('post_id');if(S.demo){S.comments[id]||=[];S.comments[id].push({id:crypto.randomUUID(),author_id:S.user.id,body:v('body'),profiles:S.profile});notify('Commentaire fictif ajouté.');closeModal()}else{checkResult(await(await getClient()).from('comments').insert({post_id:id,author_id:S.user.id,body:v('body')}));await commentsModal(id)}break;}
case 'reportForm':{if(!v('reason'))throw Error('Précise la raison du signalement.');if(!S.demo)checkResult(await(await getClient()).from('content_reports').insert({reporter_id:S.user.id,post_id:v('target')==='post'?v('id'):null,comment_id:v('target')==='comment'?v('id'):null,reason:v('reason')}));closeModal();notify('Signalement enregistré pour examen manuel, sans délai de réponse garanti.');break;}
case 'feedSearchForm':{S.feedSearch=v('search');S.feedPage=0;await loadFeed();render();break;}
case 'passwordForm':{const password=String(data.get('password')||'');if(password.length<10||password!==String(data.get('confirm')))throw Error('Les deux mots de passe doivent correspondre et contenir au moins 10 caractères.');checkResult(await(await getClient()).auth.updateUser({password}));S.recovery=false;closeModal();notify('Mot de passe mis à jour.');break;}
}}catch(err){notify(message(err));const error=form.querySelector('#journeyDateError');if(error){error.textContent=message(err);error.hidden=false;}if(form.getAttribute('id')==='authForm')$('#authInfo').textContent=message(err)}finally{S.authBusy=false;if(button)button.disabled=false}});
function network(){$('#net').hidden=navigator.onLine}window.addEventListener('online',network);window.addEventListener('offline',network);network();document.addEventListener('visibilitychange',()=>{tickTimer();if(!document.hidden&&S.user&&$('#headerDate').textContent!==new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})){if(!$('#modal').open)render()}});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installEvent=e});
try{if(localStorage.getItem('sobrizen-theme')==='dark')document.body.classList.add('dark')}catch{}
const progression=createProgress({S,getClient,ownRows,checkResult,privateWrite,message,notify,modal,closeModal,download,greeting,nextStep,journeyDateSummary,refresh:()=>refresh(),render:()=>render(),openCheck:(...args)=>checkModal(...args)});
initGames();
