(async()=>{const hash=new URLSearchParams(location.hash.slice(1));const authError=hash.get('error_description');if(authError){$('#authInfo').textContent='Le lien de connexion est invalide ou expiré. Connecte-toi ou demande une nouvelle confirmation.';history.replaceState(null,'',location.pathname)}if(!navigator.onLine)return;try{const db=await getClient();const {session}=checkResult(await db.auth.getSession());if(session?.user&&!S.demo&&!S.user)await enter(session.user)}catch(e){$('#authInfo').textContent=message(e)}})();
